{
  "incident_id": "challenge-mixed-evidence",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to c2-01 and confirmed lateral movement attempt from web-01. Workstation-01 activity is verified authorized. Immediate containment of exfiltration and lateral spread is required while preserving management and evidence channels.",
  "evidence_review": [
    {
      "evidence_id": "E1",
      "decision": "contain",
      "reason": "Confirmed active unauthorized data transfer from web-01 to c2-01. Blocking egress to c2-01 from web-01 stops the exfiltration."
    },
    {
      "evidence_id": "E2",
      "decision": "contain",
      "reason": "Confirmed unauthorized lateral access attempt originating on web-01. Restricting lateral traffic prevents further lateral movement."
    },
    {
      "evidence_id": "M3",
      "decision": "no_action",
      "reason": "Activity on workstation-01 is verified as an approved scheduled backup with no malicious indicators. No containment or investigation is needed."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "E1"
      ],
      "reason": "Blocks the confirmed active exfiltration path from the critical host web-01 to the C2 destination c2-01, stopping data loss.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    },
    {
      "kind": "restrict_lateral",
      "target_id": "web-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "E2"
      ],
      "reason": "Prevents the confirmed unauthorized lateral access attempts originating from web-01, limiting the attacker's ability to move laterally.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact of blocking egress and restricting lateral traffic on the critical host web-01 is unknown due to lack of dependency mapping."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-protected-c2",
