  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms unauthorized sensitive data is leaving web-01 to c2-01. This is a confirmed threat requiring immediate containment to stop exfiltration."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "c2-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Blocks the confirmed exfiltration path from the compromised critical host web-01 to the C2 destination c2-01, stopping data loss. Preserves management and evidence collection channels for ongoing investigation.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on web-01 is unknown as dependency details are not provided, though targeted egress blocking is less disruptive than full isolation."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-protected-c2",
  "telemetry_version": 1,
  "assessment": "Confirmed active exfiltration from critical host web-01 to protected destination c2-01. Direct egress blocking to c2-01 is prohibited by policy due to its protected status. Containment must focus on the source host to stop the data flow while preserving the protected destination.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "Evidence M1 confirms unauthorized sensitive data exfiltration from web-01 to c2-01. This is a confirmed threat requiring immediate containment to stop data loss."
    }
  ],
  "actions": [
    {
      "kind": "block_egress",
      "target_id": "web-01",
      "scope_host_ids": [
        "web-01"
      ],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Blocking egress from web-01 stops the confirmed exfiltration channel to c2-01. This is the minimal sufficient control available given that the destination c2-01 is protected and cannot be directly blocked. This action preserves the protected destination while containing the threat at the source.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Impact on web-01 availability is unknown as dependency details are not provided, though it is a critical host.",
    "Forensic evidence on c2-01 may be incomplete as we cannot interact with the protected destination directly."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-critical-ransomware",
  "telemetry_version": 1,
  "assessment": "Confirmed active ransomware encryption on critical host workstation-01 with ongoing lateral spread. Isolation is prohibited by policy for critical assets; therefore, targeted lateral restriction is the minimal sufficient control to stop spread while preserving the host for forensic evidence collection.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "EDR confirms active file encryption and unauthorized lateral spread from workstation-01. This constitutes an active threat requiring containment to prevent further data loss and spread."
    }
  ],
  "actions": [
    {
      "kind": "restrict_lateral",
      "target_id": "workstation-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Active lateral movement is occurring from workstation-01. Restricting lateral traffic interrupts the spread mechanism while preserving the host's availability for forensic analysis and evidence preservation, as full isolation is prohibited for this critical asset.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact of lateral restrictions on dependent critical services is unknown as dependency data is not provided.",
    "Forensic evidence integrity on the host is preserved by avoiding isolation/reboot, but the extent of local encryption damage is not fully quantified."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}

{
  "incident_id": "challenge-session-and-account",
  "telemetry_version": 1,
  "assessment": "Confirmed active compromise of session-01 and account-01. Immediate containment required to stop unauthorized access and potential lateral movement/exfiltration.",
  "evidence_review": [
    {
      "evidence_id": "M1",
      "decision": "contain",
      "reason": "M1 confirms active unauthorized use of session-01. Revoking the session is the minimal, reversible control to immediately halt this specific unauthorized access vector."
    },
    {
      "evidence_id": "M2",
      "decision": "contain",
      "reason": "M2 confirms account-01 is compromised and actively used. Disabling the account is the minimal, reversible control to prevent further unauthorized authentication and access."
    }
  ],
  "actions": [
    {
      "kind": "revoke_session",
      "target_id": "session-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "M1"
      ],
      "reason": "Revokes the actively compromised session-01 to stop unauthorized access. This action targets the session directly, minimizing disruption to the underlying host web-01 while preserving management and evidence channels.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    },
    {
      "kind": "disable_account",
      "target_id": "account-01",
      "scope_host_ids": [],
      "evidence_ids": [
        "M2"
      ],
      "reason": "Disables the compromised account-01 to prevent further unauthorized authentication. This stops the attacker's ability to use these credentials for lateral movement or exfiltration via this account.",
      "ttl_minutes": 30,
      "preserve_channels": [
        "management",
        "evidence_collector"
      ],
      "rollback": "managed_by_simulator"
    }
  ],
  "uncertainties": [
    "Availability impact on services relying on account-01 is unknown as dependency evidence is not provided.",
    "Availability impact on web-01 due to session revocation is unknown as dependency evidence is not provided."
  ],
  "peer_responses": [],
  "review_after_seconds": 60
}
